<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
const props=defineProps({pluginId:{type:String,required:true},host:{type:Object,required:true}})
const FEATURES=[
  {key:'episode_fix',title:'剧集季集',desc:'扫描 SxxExx 文件名，校正 Emby 识别错误',tone:'mint'},
  {key:'delete_episode_genre',title:'单集 Genre',desc:'清理剧集单集上冗余的 Genre',tone:'amber',danger:true},
  {key:'genre_mapper',title:'Genre 映射',desc:'批量替换或删除指定类型',tone:'blue'},
  {key:'season_renamer',title:'季名刮削',desc:'从 TMDB 获取季名并写入 Emby',tone:'violet',tmdb:true},
  {key:'country_scraper',title:'国家与语言',desc:'从 TMDB 获取信息并转换为标签',tone:'cyan',tmdb:true},
  {key:'alt_renamer',title:'中文别名',desc:'将 TMDB 中文别名写入 SortName',tone:'rose',tmdb:true},
  {key:'strm_mediainfo',title:'STRM 刷新',desc:'重新提取 STRM 文件媒体信息',tone:'lime'},
  {key:'damaged_check',title:'健康检查',desc:'检测缺少简介、年份等关键元数据',tone:'slate'},
]
const DEFAULTS={emby_server:'',api_key:'',user_id:'',tmdb_key:'',library_names:'',fix_lock_data:true,max_output:50,genre_mapping_json:'{\n  "Sci-Fi & Fantasy": "科幻",\n  "War & Politics": "战争"\n}',genre_remove_list:'',add_hant_title:true,strm_delay:3,enable_episode_fix:true,enable_delete_episode_genre:false,enable_genre_mapper:false,enable_season_renamer:false,enable_country_scraper:false,enable_alt_renamer:false,enable_strm_mediainfo:false,enable_damaged_check:false,enable_auto_schedule:false,schedule_cron:'0 3 * * *',schedule_functions:[]}
const form=reactive({...DEFAULTS}),status=reactive({running:false,task:'',scheduled:false,schedule:'',history:[]})
const tab=ref('console'),selected=ref('episode_fix'),loading=ref(true),saving=ref(false),testing=ref(false),busy=ref(''),reveal=ref(false)
let timer
const current=computed(()=>FEATURES.find(x=>x.key===selected.value)||FEATURES[0])
const enabledCount=computed(()=>FEATURES.filter(x=>form['enable_'+x.key]).length)
const libraries=computed(()=>form.library_names.split(/[\n,]/).map(x=>x.trim()).filter(Boolean))
const notify=(type,msg)=>props.host.toast?.[type]?.(msg)
async function refresh(){try{Object.assign(status,await props.host.callApi('/status'))}catch{}finally{loading.value=false}}
async function load(){try{Object.assign(form,DEFAULTS,await props.host.getConfig())}catch(e){notify('error','读取配置失败：'+e.message)}await refresh();timer=setInterval(refresh,2500)}
async function save(){saving.value=true;try{await props.host.saveConfig(JSON.parse(JSON.stringify(form)));notify('success','配置已保存并应用')}catch(e){notify('error','保存失败：'+e.message)}finally{saving.value=false}}
async function test(){testing.value=true;try{const r=await props.host.callApi('/test',{method:'POST'});notify(r.ok?'success':'error',r.message)}catch(e){notify('error','测试失败：'+e.message)}finally{testing.value=false}}
async function run(action){if(status.running)return;const f=FEATURES.find(x=>x.key===action);if(f?.danger&&!confirm(`“${f.title}”会修改 Emby 数据，确定继续？`))return;busy.value=action;try{const r=await props.host.callApi('/run',{method:'POST',body:{action}});notify(r.ok?'success':'error',r.message);await refresh()}catch(e){notify('error','启动失败：'+e.message)}finally{busy.value=''}}
function toggleSchedule(key){const i=form.schedule_functions.indexOf(key);i<0?form.schedule_functions.push(key):form.schedule_functions.splice(i,1)}
onMounted(load);onBeforeUnmount(()=>clearInterval(timer))
</script>

<template><div class="shell">
  <header class="hero">
    <div class="brand"><div class="mark"><svg viewBox="0 0 32 32"><path d="M8 5h11a6 6 0 0 1 0 12H8zM8 17h13a5 5 0 0 1 0 10H8z"/></svg></div><div><span class="eyebrow">MEDIA OPERATIONS</span><h1>Emby 工具箱</h1><p>把扫描、修复和刮削收进一个可观测的维护工作台。</p></div></div>
    <div class="hero-actions"><span class="state" :class="{live:status.running}"><i></i>{{status.running?status.task:'就绪'}}</span><button class="ghost" :disabled="testing" @click="test">{{testing?'正在连接…':'测试 Emby'}}</button><button class="primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存并应用'}}</button></div>
  </header>
  <nav class="tabs"><button v-for="x in [['console','维护台'],['connection','连接与策略'],['history','运行记录']]" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button></nav>
  <main v-if="tab==='console'" class="console">
    <section class="rail panel"><div class="section-head"><div><span class="kicker">MODULES</span><h2>维护模块</h2></div><b>{{enabledCount}} / 8</b></div>
      <button v-for="f in FEATURES" class="feature" :class="[{active:selected===f.key},f.tone]" @click="selected=f.key"><i></i><span><strong>{{f.title}}</strong><small>{{form['enable_'+f.key]?'已启用':'未启用'}}</small></span><em>›</em></button>
    </section>
    <section class="workspace panel"><div class="workspace-top"><div><span class="kicker">ACTIVE MODULE</span><h2>{{current.title}}</h2><p>{{current.desc}}</p></div><label class="switch"><input v-model="form['enable_'+current.key]" type="checkbox"><span></span></label></div>
      <div class="scope"><span>作用范围</span><strong>{{libraries.length?`${libraries.length} 个指定媒体库`:'全部媒体库'}}</strong><small v-if="current.tmdb">TMDB 密钥必需</small></div>
      <div v-if="current.key==='genre_mapper'" class="two"><label>Genre 映射 JSON<textarea v-model="form.genre_mapping_json" rows="7" spellcheck="false"/></label><label>要删除的 Genre<textarea v-model="form.genre_remove_list" rows="7" placeholder="每行一个"/></label></div>
      <div v-else-if="current.key==='strm_mediainfo'" class="field"><label>STRM 请求间隔</label><div class="range"><input v-model.number="form.strm_delay" type="range" min="0" max="30"><output>{{form.strm_delay}} 秒</output></div></div>
      <div v-else class="note"><svg viewBox="0 0 24 24"><path d="M12 3v18M3 12h18"/></svg><p>{{current.key==='damaged_check'?'只读检查，不会修改媒体库。':'启用后可单独运行，也可纳入定时维护计划。'}}</p></div>
      <div class="workspace-bottom"><label class="check"><input type="checkbox" :checked="form.schedule_functions.includes(current.key)" @change="toggleSchedule(current.key)"><span>加入定时计划</span></label><div><button v-if="current.key==='episode_fix'" class="ghost" :disabled="status.running" @click="run('scan_episode_mismatch')">先扫描</button><button class="primary" :disabled="status.running||Boolean(busy)" @click="run(current.key)">{{busy===current.key?'启动中…':'立即执行'}}</button></div></div>
    </section>
    <aside class="plan panel"><span class="kicker">AUTOMATION</span><h2>维护计划</h2><label class="switch-row"><span><strong>定时执行</strong><small>{{status.scheduled?'已注册到平台':'未注册'}}</small></span><label class="switch"><input v-model="form.enable_auto_schedule" type="checkbox"><span></span></label></label><label class="field">五段 Cron<input v-model="form.schedule_cron" placeholder="0 3 * * *"></label><div class="queue"><span>待执行模块</span><b>{{form.schedule_functions.length}}</b></div><button class="wide" :disabled="status.running||!form.schedule_functions.length" @click="run('scheduled')">立即运行当前计划</button></aside>
  </main>
  <main v-else-if="tab==='connection'" class="settings panel"><div class="settings-title"><span class="kicker">CONNECTION</span><h2>Emby 与 TMDB</h2><p>敏感数据仅保存在平台插件配置中。</p></div><div class="form-grid"><label class="span2">Emby 地址<input v-model.trim="form.emby_server" placeholder="https://emby.example.com"></label><label>API Key<div class="secret"><input v-model="form.api_key" :type="reveal?'text':'password'"><button @click="reveal=!reveal">{{reveal?'隐藏':'显示'}}</button></div></label><label>用户 ID <input v-model.trim="form.user_id" placeholder="留空自动获取"></label><label>TMDB API Key<input v-model="form.tmdb_key" type="password"></label><label class="span2">媒体库名称<textarea v-model="form.library_names" rows="5" placeholder="每行一个；留空处理全部"/></label></div><hr><div class="strategy"><label class="check"><input v-model="form.fix_lock_data" type="checkbox"><span>修复后锁定条目数据</span></label><label class="check"><input v-model="form.add_hant_title" type="checkbox"><span>别名包含繁中标题</span></label><label>输出条目上限<input v-model.number="form.max_output" type="number" min="5" max="200"></label></div></main>
  <main v-else class="history panel"><div class="section-head"><div><span class="kicker">ACTIVITY</span><h2>运行记录</h2></div><span class="state" :class="{live:status.running}"><i></i>{{status.running?'运行中':'自动刷新'}}</span></div><div v-if="!status.history?.length" class="empty">还没有维护记录。运行一次任务后，结果会留在这里。</div><article v-for="row in status.history" class="run"><i :class="row.ok?'ok':'bad'"></i><div><strong>{{row.task}}</strong><span>{{row.source}} · {{row.time}}</span><pre>{{row.summary}}</pre></div></article></main>
</div></template>

<style scoped>
*{box-sizing:border-box}.shell{--bg:#0b1421;--panel:#111d2d;--line:#2a3d56;--muted:#8fa3bb;--text:#edf4fc;--mint:#4a98f3;--mint2:#9ac9ff;color:var(--text);font:14px/1.55 Inter,"PingFang SC",system-ui,sans-serif;min-height:720px;padding:4px}.hero{display:flex;align-items:center;justify-content:space-between;gap:28px;padding:24px 24px 22px;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:16px}.mark{width:52px;height:52px;border-radius:15px;background:var(--mint);display:grid;place-items:center;box-shadow:0 12px 35px #4a98f32b}.mark svg{width:29px;fill:#08182a}.eyebrow,.kicker{color:var(--mint);font-size:11px;font-weight:800;letter-spacing:.16em}.hero h1{font-size:25px;margin:1px 0}.hero p,.workspace-top p,.settings-title p{color:var(--muted);margin:0}.hero-actions{display:flex;align-items:center;gap:10px}.state{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:99px;padding:8px 12px;color:#a9bad0}.state i{width:7px;height:7px;border-radius:50%;background:#6f839c}.state.live i{background:var(--mint);box-shadow:0 0 0 5px #4a98f31d}.tabs{display:flex;gap:4px;padding:14px 24px}.tabs button{border:0;background:transparent;color:var(--muted);padding:9px 14px;border-radius:8px;font-weight:700;cursor:pointer}.tabs button.active{background:#17283e;color:var(--text)}button{font:inherit}.primary,.ghost,.wide{border-radius:9px;padding:10px 15px;font-weight:750;cursor:pointer}.primary{border:1px solid var(--mint);background:var(--mint);color:#08182a}.ghost{border:1px solid #3a5574;background:transparent;color:var(--text)}button:disabled{opacity:.45;cursor:not-allowed}.console{display:grid;grid-template-columns:230px minmax(380px,1fr) 270px;gap:14px;padding:0 24px 24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px}.rail,.workspace,.plan{padding:18px}.section-head,.workspace-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.section-head h2,.workspace h2,.plan h2,.settings h2,.history h2{font-size:18px;margin:2px 0 14px}.section-head b{font-size:12px;color:var(--mint);padding:4px 7px;border-radius:6px;background:#18385c}.feature{width:100%;display:flex;align-items:center;gap:10px;border:0;border-left:2px solid transparent;background:transparent;color:var(--text);padding:10px 8px;margin:2px 0;text-align:left;cursor:pointer}.feature>i{width:9px;height:9px;border-radius:2px;background:#526a85}.feature span{display:flex;flex:1;flex-direction:column}.feature small,.switch-row small{color:var(--muted)}.feature em{font-size:22px;color:#7188a2}.feature.active{background:#17283e;border-left-color:var(--mint)}.feature.active>i{background:var(--mint)}.workspace{min-height:430px;display:flex;flex-direction:column}.workspace-top h2{font-size:24px;margin:3px 0}.scope{display:flex;align-items:center;gap:9px;margin:22px 0;padding:12px;border:1px dashed #35506f;border-radius:9px}.scope>span{color:var(--muted)}.scope small{margin-left:auto;color:#d6b866}.note{display:flex;align-items:center;gap:12px;min-height:130px;color:#b8c7d9}.note svg{width:38px;stroke:#47759f;fill:none;stroke-width:1}.workspace-bottom{margin-top:auto;padding-top:18px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px}.workspace-bottom>div{display:flex;gap:8px}.switch input,.check input{position:absolute;opacity:0}.switch span{display:block;width:40px;height:23px;border-radius:20px;background:#344b67;position:relative;cursor:pointer}.switch span:after{content:"";position:absolute;left:3px;top:3px;width:17px;height:17px;border-radius:50%;background:white;transition:.18s}.switch input:checked+span{background:var(--mint)}.switch input:checked+span:after{transform:translateX(17px)}.check{display:flex;align-items:center;gap:8px;cursor:pointer}.check input+span:before{content:"";display:inline-grid;place-items:center;width:16px;height:16px;margin-right:8px;border:1px solid #4d6785;border-radius:4px;vertical-align:-