n{display:grid;grid-template-columns:10px 1fr;gap:13px;padding:16px 0;border-top:1px solid var(--line)}.run>i{width:8px;height:8px;border-radius:50%;margin-top:7px}.run>i.ok{background:var(--mint)}.run>i.bad{background:#ef7070}.run div{display:grid;grid-template-columns:1fr auto}.run span{color:var(--muted);font-size:12px}.run pre{grid-column:1/-1;white-space:pre-wrap;color:#b8c7d9;font:12px/1.6 ui-monospace,monospace;max-height:140px;overflow:auto;margin:8px 0 0}.loading{opacity:.6}@media(max-width:980px){.console{grid-template-columns:210px 1fr}.plan{grid-column:1/-1}.hero{align-items:flex-start}.hero-actions{flex-wrap:wrap;justify-content:flex-end}}@media(max-width:700px){.shell{padding:0}.hero{padding:18px;flex-direction:column}.hero-actions{width:100%;justify-content:flex-start}.console{grid-template-columns:1fr;padding:0 12px 18px}.rail{display:grid;grid-template-columns:1fr 1fr;gap:3px}.rail .section-head{grid-column:1/-1}.feature{min-width:0}.workspace-bottom{align-items:flex-start;flex-direction:column}.workspace-bottom>div{width:100%}.workspace-bottom button{flex:1}.tabs{padding:10px 12px;overflow:auto}.settings,.history{margin:0 12px 18px;padding:18px}.form-grid,.strategy,.two{grid-template-columns:1fr}.span2{grid-column:auto}.run div{grid-template-columns:1fr}.run span{grid-column:1}.hero p{max-width:32ch}.state{max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
</style>
